exercises.code:
let saldo = 800
let sobregiro = false
let comisiones = 0
let movimientos = 0
for (let i = 1; i <= 6; i++) {
  if (i % 2 === 0) {
    saldo -= i * 125
  } else {
    saldo += i * 100
  }
  if (saldo < 500 && !sobregiro) {
    sobregiro = true
    comisiones += 20
  }
  if (sobregiro) {
    saldo -= 5
  }
  movimientos++
  if (saldo > 900) {
    sobregiro = false
  }
  console.log(i, saldo, sobregiro, comisiones, movimientos)
}

